<script>
export const page={name:"sales-archive-detail",path:"/sales/archive/:id",title:"封存銷售訂單詳情",requires:{permissions:["sales.view"]}};
</script>
<script setup>
import {nextTick,onBeforeUnmount,ref,watch} from "vue";
import {useRoute} from "vue-router";
import appConfig from "@config/app.js";
import PageHeader from "@/framework/layout/PageHeader.vue";
import DataTable from "@/framework/ui/DataTable.vue";
import EllipsisCell from "@/framework/ui/EllipsisCell.vue";
import SalesOrderSourcePanel from "@/components/sales/SalesOrderSourcePanel.vue";
import SalesOrderStatusTimeline from "@/components/sales/SalesOrderStatusTimeline.vue";
import {statusLabels,statusColors} from "@/components/sales/salesOrderPresentation.js";
import {useSessionStore} from "@/stores/session.js";
import sales from "@/services/sales.js";
const route=useRoute(),session=useSessionStore(),document=ref(null),loading=ref(false),error=ref(""),showAudit=ref(false),errorRegion=ref(null),auditRegion=ref(null);let controller,auditController,generation=0;
async function load(){const current=++generation;controller?.abort();auditController?.abort();controller=new AbortController();const signal=controller.signal;document.value=null;showAudit.value=false;error.value="";loading.value=true;try{const result=await sales.getArchivedOrder(Number(route.params.id),{signal});if(!signal.aborted&&current===generation)document.value=result;}catch(cause){if(!signal.aborted&&current===generation)error.value=cause.status===404?"找不到已完成封存的訂單；請返回歷史查詢。":"歷史訂單暫不可用；請重試或確認查閱權限。";}finally{if(current===generation)loading.value=false;}if(current===generation&&error.value){await nextTick();if(current===generation&&!signal.aborted)errorRegion.value?.querySelector('[role="alert"]')?.focus();}}
watch([()=>route.params.id,()=>session.user?.id],load,{immediate:true});onBeforeUnmount(()=>{generation++;controller?.abort();auditController?.abort();});
async function fetchAudit(params){const current=generation,id=document.value.id;auditController?.abort();auditController=new AbortController();const signal=auditController.signal;const result=await sales.listArchivedAudit(id,{...params,signal});if(signal.aborted||current!==generation)throw new DOMException("Aborted","AbortError");return result;}
let focusedError;
function focusTableError(){const summary=auditRegion.value?.querySelector('[role="alert"]');if(summary&&summary!==focusedError){summary.tabIndex=-1;summary.focus();}focusedError=summary;}
const columns=[{name:"lineNo",label:"行",field:"lineNo"},{name:"sku",label:"商品快照",field:"skuCode"},{name:"quantity",label:"輸入數量",field:"quantity",align:"right"},{name:"base",label:"Base 數量",field:"orderedBaseQuantity"},{name:"unitSellingPrice",label:"單價",field:"unitSellingPrice",align:"right"},{name:"lineAmount",label:"行總額",field:"lineAmount",align:"right"},{name:"lineNote",label:"行備註",field:"lineNote"}],auditColumns=[{name:"occurredAt",label:"時間",field:"occurredAt"},{name:"action",label:"操作",field:"action"},{name:"actorLabel",label:"操作者",field:"actorLabel"},{name:"outcome",label:"結果",field:"outcome"},{name:"reason",label:"原因",field:"reason"}];
function timestamp(value){return new Intl.DateTimeFormat("zh-HK",{timeZone:"Asia/Hong_Kong",dateStyle:"short",timeStyle:"short"}).format(new Date(value));}
</script>
<template><div class="q-pa-md" :aria-busy="loading"><PageHeader :title="document?`封存訂單 ${document.number}`:'封存銷售訂單詳情'" subtitle="歷史唯讀；此頁只顯示封存時的快照。"><template #actions><q-btn flat label="返回歷史查詢" to="/sales/archive" /><q-btn flat label="Active 訂單" to="/sales/orders" /></template></PageHeader>
 <q-skeleton v-if="loading" type="rect" aria-label="載入歷史訂單" /><div v-else-if="error" ref="errorRegion"><q-banner role="alert" tabindex="-1" class="bg-negative text-white">{{ error }}<template #action><q-btn flat label="重試" @click="load" /></template></q-banner></div>
 <template v-else-if="document"><div class="row items-center q-gutter-sm q-mb-md"><q-badge color="primary" label="歷史唯讀" /><q-badge :color="statusColors[document.status]" :label="statusLabels[document.status]" /><span>版本 {{ document.version }}</span><span>封存時間 {{ timestamp(document.archivedAt) }}；批次 #{{ document.archiveBatchId }}</span></div>
  <q-card flat bordered class="q-mb-md"><q-card-section><h2 class="text-h6 q-ma-none q-mb-md">訂單資料與快照</h2><dl class="row q-col-gutter-md archive-text"><div class="col-12 col-md-6"><dt>客戶快照</dt><dd class="q-ml-none">{{ document.customerCode }} — {{ document.customerName }}</dd></div><div class="col-12 col-md-6"><dt>履約倉庫快照</dt><dd class="q-ml-none">{{ document.warehouseCode }} — {{ document.warehouseName }}</dd></div><div class="col-12 col-md-6"><dt>總額</dt><dd class="q-ml-none">{{ document.currencyCode }} {{ document.totalAmount }}</dd></div><div class="col-12 col-md-6"><dt>訂單日期／要求送貨日期</dt><dd class="q-ml-none">{{ document.orderDate }}／{{ document.requestedDeliveryDate||'未設定' }}</dd></div><div class="col-12 col-md-6"><dt>付款條款</dt><dd class="q-ml-none">{{ document.paymentTermName||'未設定' }}</dd></div><div class="col-12 col-md-6"><dt>客戶 PO</dt><dd class="q-ml-none">{{ document.customerPoReference||'—' }}</dd></div><div class="col-12"><dt>備註</dt><dd class="q-ml-none archive-notes">{{ document.notes||'—' }}</dd></div></dl></q-card-section></q-card>
  <h2 class="text-h6 q-ma-none q-mb-md">訂單明細</h2><DataTable :rows="document.lines" :columns="columns" :initial-pagination="{page:1,rowsPerPage:appConfig.defaultPageSize,sortBy:null,descending:false}"><template #body-cell-sku="{row}"><EllipsisCell :text="`${row.skuCode} — ${row.skuName}`" /></template><template #body-cell-quantity="{row}"><q-td class="text-right">{{ row.quantity }} {{ row.uomCode }}</q-td></template><template #body-cell-base="{row}"><q-td><div>Ordered {{ row.orderedBaseQuantity }}</div><div>Reserved {{ row.reservedBaseQuantity }}</div><div>Backorder {{ row.backorderedBaseQuantity }}</div><div>Fulfilled {{ row.fulfilledBaseQuantity }}</div><div>Cancelled {{ row.cancelledBaseQuantity }}</div></q-td></template><template #body-cell-lineNote="{row}"><EllipsisCell :text="row.lineNote" /></template></DataTable>
  <section class="q-my-md"><h2 class="text-h6 q-ma-none q-mb-md">Reservation 歷史參考</h2><p>累計釋放是歷史數量，不加入目前需求數量的等式。全訂單最多列出 500 筆參考。</p><div v-for="line in document.lines" :key="line.id" class="q-mb-md archive-text"><h3 class="text-subtitle1 q-ma-none">第 {{ line.lineNo }} 行：累計釋放 {{ line.releasedBaseQuantity }} Base</h3><p v-if="line.reservationsTruncated" role="status">參考未列全：顯示 {{ line.reservations.length }}／{{ line.reservationsTotal }} 筆；累計釋放仍包括完整歷史。</p><p v-else>共 {{ line.reservationsTotal }} 筆參考。</p><ul><li v-for="reference in line.reservations" :key="reference.id">Reservation #{{ reference.inventoryReservationId }}：{{ reference.status }}；原始 {{ reference.originalBaseQuantity }}，已耗用 {{ reference.consumedBaseQuantity }}，已釋放 {{ reference.releasedBaseQuantity }}，未完成 {{ reference.outstandingBaseQuantity }} Base</li></ul></div></section>
  <SalesOrderSourcePanel :order="document" /><SalesOrderStatusTimeline :history="document.history" :truncated="document.historyTruncated" />
  <section class="q-my-md"><h2 class="text-h6 q-ma-none q-mb-md">審計紀錄</h2><q-btn v-if="!showAudit" flat label="查看審計紀錄" @click="showAudit=true" /><div v-if="showAudit" ref="auditRegion"><DataTable :key="`${session.user?.id}:${document.id}`" :fetch="fetchAudit" @vue:updated="focusTableError" :columns="auditColumns" :initial-pagination="{page:1,rowsPerPage:appConfig.defaultPageSize,sortBy:'occurredAt',descending:true}"><template #body-cell-occurredAt="{row}"><q-td>{{ timestamp(row.occurredAt) }}</q-td></template><template #body-cell-actorLabel="{row}"><EllipsisCell :text="row.actorLabel" /></template><template #body-cell-reason="{row}"><EllipsisCell :text="row.reason" /></template><template #no-data><p role="status">沒有此歷史訂單的審計紀錄。</p></template></DataTable></div></section>
 </template></div></template>
<style scoped>.archive-text{overflow-wrap:anywhere}.archive-notes{white-space:pre-wrap}</style>
